local M = class("CastingSwordMainControl",LikeOO.OOControlBase)

function M:onEnter()
    audio:SendEvtBGM("Set_State_ZhuJianDaHui")
    M.super.onCreate(self)
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
        self:updateMsg("common_refresh",nil,"parent")
    elseif msg == "btn_openBtn1" then
        -- 全民铸剑
        self.m_view:playTabAnim(false)
        self:setOnceTimer(0.1,function()
            self:openView("CastingSwordMeeting.CastingSwordTask", self.m_model.m_response)
        end)
    elseif msg == "btn_openBtn2" then
        -- 群英试炼
        self.m_view:playTabAnim(false)
        self:setOnceTimer(0.1,function()
            local openId = 411
            local activeData = UserDataManager:getActivesDataByOpenId(openId)
            local version = 13
            if activeData ~= nil then
                version = activeData.version or 13--版本号
            end
            local params = {
                is_token = false,
                open_id = openId,
                active_data = activeData,
                version = version}
            self:openView("Chivalry.ChivalryBattle", params)
        end)
    elseif msg == "btn_openBtn3" then
        -- 明星好礼 
        self.m_view:playTabAnim(false)
        self:setOnceTimer(0.1,function()
            local heroDraw = ConfigManager:getCommonValueById(120,0)
            if heroDraw == 1 then
                self:openView("LuckyDraw.HeroDraw")
            else
                self:openView("LuckyDraw.LuckyDraw")
            end
        end)
    elseif msg == "btn_openBtn4" then
        -- 江湖大事件
        self.m_view:playTabAnim(false)
        self:setOnceTimer(0.1,function()
            self:openView("CastingSwordMeeting.CastingSwordRank")
        end)
    elseif msg == "btn_openBtn5" then
        -- 决战光明顶
        self.m_view:playTabAnim(false)
        self:setOnceTimer(0.1,function()
            self:openView("HalfAnniversary.HalfAnniversaryLottery", {open_id = 331})
            --self:openView("CastingSwordMeeting.CastingSwordSinatv", {viewType = 2, open_id = self.m_view.tab_Node[5].open_id})
        end)
    else
        self:tryOpenItem(msg)
    end
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

--跳转页签
function M:tryOpenItem(btn_name)
    local item = self.m_model:getItem(btn_name)
    if item == nil then
        return
    end
    if item.open_id == 259 or item.open_id == 243 then
        self:openView("TopUpGiftBag", {actives = UserDataManager.m_actives, open_id = self.m_is_token, active_id = item.active_id})
        return
    elseif item.open_id == 251 then
        self:openView("GiftBag", {mode = 1, actives = UserDataManager.m_actives, open_id = self.m_is_token, active_id = item.active_id})
    end
end

function M:destroy()
    SceneManager:getCurSceneView():setBGMusic()
    M.super.destroy(self)
end

return M